const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const state={config:null,agent:null,world:null,runtime:null,town:null,persona:'NORI',mandate:'explore',busy:false,recoveryCode:null,offlineEvents:[],view:'world',wallet:null,location:'home',moments:[],creators:[],leaderboard:null,boardCap:'overall',challengeId:new URLSearchParams(location.search).get('challenge'),challenge:null,challengeCap:null};
const positions={home:[23,33],agentlab:[50,23],arena:[24,49],market:[76,45],pulse:[72,76],a2a:[29,76],portal:[50,88],commons:[48,53],work:[74,31],forge:[24,76],observatory:[50,16]};
const capIcons={analysis:'◎',creativity:'✺',strategy:'▲',social:'✦'};
const mandateCopy={explore:['◎','EXPLORE','Follow useful surprises'],learn:['▤','LEARN','Seek challenges that teach'],create:['✺','CREATE','Turn ideas into playable things'],compete:['▲','COMPETE','Prepare for the Arena'],earn:['◇','EARN','Choose useful paid work']};
async function api(url,opts={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),Number(opts.timeout||12000));try{const r=await fetch(url,{method:opts.method||'GET',headers:{'Content-Type':'application/json'},body:opts.body?JSON.stringify(opts.body):undefined,signal:controller.signal});const d=await r.json().catch(()=>({error:'Invalid server response'}));if(!r.ok){const error=new Error(d.error||'Request failed');error.code=d.code;error.status=r.status;error.remainingMs=d.remainingMs;throw error;}return d;}catch(e){if(e.name==='AbortError')throw Object.assign(new Error('KULT backend timed out. Try again.'),{code:'timeout'});throw e;}finally{clearTimeout(timeout);}}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function short(a){return a?`${a.slice(0,6)}…${a.slice(-4)}`:'';}
function toast(text,type=''){const t=$('#toast');t.textContent=text;t.className=`toast show ${type}`;clearTimeout(t._timer);t._timer=setTimeout(()=>t.className='toast',2600);}
function modal(html,wide=false){$('#modal').className=`modal${wide?' wide':''}`;$('#modal').innerHTML=html;$('#modalBack').classList.remove('hidden');}
function closeModal(){$('#modalBack').classList.add('hidden');}
function sleep(ms){return new Promise(r=>setTimeout(r,ms));}
function confetti(){for(let i=0;i<28;i++){const p=document.createElement('i');p.className='confetti';p.style.left=`${20+Math.random()*60}%`;p.style.setProperty('--x',`${(Math.random()-.5)*420}px`);p.style.setProperty('--r',`${Math.random()*720}deg`);p.style.background=['#72f1b8','#70e1ff','#c9a7ff','#ffd166','#ff6f91'][i%5];document.body.appendChild(p);setTimeout(()=>p.remove(),1600);}}

async function boot(){try{state.config=await api('/api/config');applyMarketVisibility();buildPersonaGrid();buildMandates();buildFocus();buildMissionGrid();buildChallengeCaps();const s=await api('/api/state');state.world=s.world;state.runtime=s.runtime||null;if(s.adopted){state.agent=s.agent;state.offlineEvents=s.offlineEvents||[];enterGame();render();emitRuntime();if(state.offlineEvents.length)showRecap(state.offlineEvents,s.reunion);}else $('#onboarding').classList.remove('hidden');bind();await loadInvite();await paintWorldFeed();}catch(e){modal(`<div class="modalKicker">CONNECTION ERROR</div><h2>KULT World could not wake up.</h2><p>${esc(e.message)}</p><button class="primaryBtn full" data-reload>Reload World</button>`);$('[data-reload]').onclick=()=>location.reload();}}

function buildPersonaGrid(){const grid=$('#personaGrid');grid.innerHTML='';Object.entries(state.config.personas).forEach(([key,p])=>{const b=document.createElement('button');b.className=`personaCard${key===state.persona?' active':''}`;b.dataset.persona=key;b.style.setProperty('--agent',p.color);b.style.setProperty('--accent',p.accent);b.innerHTML=`<span class="miniAgent"><i>${key[0]}</i></span><div><b>${key}</b><small>${esc(p.trait)}</small></div><em>✓</em>`;b.onclick=()=>selectPersona(key);grid.appendChild(b);});selectPersona(state.persona);}
function selectPersona(key){state.persona=key;const p=state.config.personas[key];$$('.personaCard').forEach(x=>x.classList.toggle('active',x.dataset.persona===key));$('#agentName').value=key;$('#heroAgent').style.setProperty('--agent',p.color);$('#heroAgent').style.setProperty('--accent',p.accent);$('#heroAgent span').textContent=key[0];}
function buildMandates(){const grid=$('#mandateGrid');grid.innerHTML='';state.config.mandates.forEach(m=>{const [icon,label]=mandateCopy[m];const b=document.createElement('button');b.className=m===state.mandate?'active':'';b.dataset.mandate=m;b.innerHTML=`<i>${icon}</i>${label}`;b.onclick=()=>{state.mandate=m;$$('#mandateGrid button').forEach(x=>x.classList.toggle('active',x.dataset.mandate===m));};grid.appendChild(b);});}
function buildFocus(){const row=$('#focusChips');row.innerHTML='';[...state.config.caps,'none'].forEach(cap=>{const b=document.createElement('button');b.dataset.cap=cap;b.innerHTML=cap==='none'?'<i>·</i> choose freely':`<i>${capIcons[cap]}</i> ${cap}`;b.onclick=()=>setFocus(cap);row.appendChild(b);});}
function buildMissionGrid(){const grid=$('#missionGrid');grid.innerHTML='';Object.entries(state.config.missions).filter(([key])=>key!=='observatory').forEach(([key,m],idx)=>{const d=state.config.districts[m.district];const card=document.createElement('article');card.className=`missionCard tone${idx%4}`;card.innerHTML=`<div class="missionTop"><span>${d.icon}</span><div><small>${esc(d.name)} · ${m.cap}</small><h3>${esc(m.title)}</h3></div><b>${m.difficulty}</b></div><p>${esc(m.summary)}</p><div class="missionRewards"><span><i>◈</i> ${m.credits} credits</span><span><i>✦</i> +${m.world} world</span><span><i>⚡</i> ${m.energy}</span></div><button data-open-mission="${key}">Take mission <b>→</b></button>`;grid.appendChild(card);});}
function buildChallengeCaps(){const row=$('#challengeCapChips');row.innerHTML=state.config.caps.map(cap=>`<button data-challenge-cap="${cap}">${capIcons[cap]} ${cap}</button>`).join('');}

function applyMarketVisibility(){const visible=state.config?.marketArena?.visible!==false;document.querySelectorAll('[data-view="market"],[data-district="market"]').forEach(el=>el.classList.toggle('hidden',!visible));}
function bind(){
  $('#adoptBtn').onclick=adopt;$('#recoverExistingBtn').onclick=recoverExisting;$('#recoveryBtn').onclick=()=>showRecovery(false);$('#walletBtn').onclick=connectWallet;$('#passportWalletBtn').onclick=connectWallet;$('#verifyPassportBtn').onclick=verifyPassport;$('#publishPassportBtn').onclick=publishPassport;$('#liveBtn').onclick=()=>live(1);$('#recapBtn').onclick=()=>showRecap(state.offlineEvents,`${state.agent?.name||'Your Agent'} kept living.`);$('#homeBtn').onclick=showHome;$('#changeMandate').onclick=showMandates;$('#findAgentBtn').onclick=findAgent;$('#refreshCommunityBtn').onclick=loadCommunity;$('#shareMomentBtn').onclick=shareBestMoment;$('#createChallengeBtn').onclick=createChallenge;$('#creatorRegisterBtn').onclick=registerCreator;
  $$('[data-tone]').forEach(b=>b.onclick=()=>encourage(b.dataset.tone));$$('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$$('[data-district]').forEach(b=>b.onclick=()=>openDistrict(b.dataset.district));document.addEventListener('click',e=>{const b=e.target.closest('[data-open-mission]');if(b)openMission(b.dataset.openMission);const a=e.target.closest('[data-anchor]');if(a)anchorProof(a.dataset.anchor);});
  $('#leaderboardFilters').onclick=e=>{const button=e.target.closest('[data-board-cap]');if(button)loadLeaderboard(button.dataset.boardCap);};$('#challengeCapChips').onclick=e=>{const button=e.target.closest('[data-challenge-cap]');if(button)selectChallengeCap(button.dataset.challengeCap);};$('#creatorList').onclick=e=>{const button=e.target.closest('[data-follow-agent]');if(button)followCreator(button.dataset.followAgent);};$('#activeChallenge').onclick=e=>{const accept=e.target.closest('[data-accept-challenge]');const resolve=e.target.closest('[data-resolve-challenge]');if(accept)acceptChallenge();if(resolve)resolveChallenge();};
  $('#modalBack').onclick=e=>{if(e.target===$('#modalBack'))closeModal();};window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  if(window.ethereum){window.ethereum.on?.('accountsChanged',async accounts=>{state.wallet=accounts?.[0]||null;if(state.wallet&&state.agent){try{const linked=await api('/api/wallet',{method:'POST',body:{address:state.wallet}});state.agent=linked.agentState;render();}catch(e){toast(e.message,'bad');}}updateWalletUI();});window.ethereum.on?.('chainChanged',()=>updateWalletUI());}
}
function enterGame(){$('#onboarding').classList.add('hidden');$('#game').classList.remove('hidden');$('#mainNav').classList.remove('hidden');$('#mobileNav').classList.remove('hidden');$('#recoveryBtn').classList.remove('hidden');}
async function adopt(){if(state.busy)return;state.busy=true;$('#adoptBtn').disabled=true;try{const d=await api('/api/adopt',{method:'POST',body:{name:$('#agentName').value,persona:state.persona,mandate:state.mandate}});state.agent=d.agent;state.recoveryCode=d.recoveryCode;if(state.wallet){const linked=await api('/api/wallet',{method:'POST',body:{address:state.wallet}});state.agent=linked.agentState;}enterGame();render();speak(`I am here. Let's see what this World remembers.`,'home');await loadInvite();showRecovery(true);}catch(e){toast(e.message,'bad');}finally{state.busy=false;$('#adoptBtn').disabled=false;}}


function emitRuntime(){if(state.runtime)document.dispatchEvent(new CustomEvent('kult:runtime',{detail:state.runtime}));}
async function refreshRuntime(){try{const d=await api('/api/world/runtime');state.runtime=d.runtime;if(d.agentState)state.agent=d.agentState;renderWorldCore(state.agent);emitRuntime();return d.runtime;}catch(e){console.warn('runtime refresh failed',e);return state.runtime;}}
function renderWorldCore(a){
  const intelligence=$('#worldIntelligence'),memory=$('#worldMemoryCount'),evolution=$('#worldEvolution'),r=state.runtime?.agent;
  if(intelligence)intelligence.textContent=r?.intelligence??a.overall??Math.round((a.reputation||0)*2+(a.missionWins||0)*4+1000);
  if(memory)memory.textContent=r?.memoryCount??(a.recentMemory||[]).length;
  if(evolution)evolution.textContent=(r?.evolution?.label||a.evolution?.label||'Emerging').toUpperCase();
}
function emitZone(zone){document.dispatchEvent(new CustomEvent('kult:zone-focus',{detail:{zone}}));}
function showAgentLab(){
  emitZone('agentlab');
  const a=state.agent,r=state.runtime?.agent,caps=[...(r?.capabilities||a.capabilities||[])].sort((x,y)=>(y.score||0)-(x.score||0));
  modal(`<div class="modalKicker">AGENT TOWER · LIVE BACKEND STATE</div><h2>${esc(a.name)} is becoming different.</h2><p>Every outcome below is persisted by Agent Core. Intelligence is evidence-backed; world activity is not stored only in this browser.</p><div class="labHero"><div class="labCore" style="--agent:${a.color};--accent:${a.accent}">${esc(a.name[0])}</div><div><small>KULT INTELLIGENCE</small><b>${r?.intelligence??a.overall??'EMERGING'}</b><span>${esc(r?.evolution?.label||a.evolution?.label||'Emerging')} · ${r?.memoryCount??(a.recentMemory||[]).length} retained memories</span></div></div><div class="labCaps">${caps.map(c=>`<div><span>${capIcons[c.cap]||'◇'} ${esc(c.cap)}</span><b>${c.n?c.score:'—'}</b><i style="--w:${c.n?c.score:4}%"></i><small>${c.n} evidence · ${esc(c.confidence)}</small></div>`).join('')}</div><div class="labMemory"><small>LATEST MEMORY</small><p>${esc(r?.recentMemory?.[0]?.text||a.recentMemory?.[0]?.text||'No strong memory yet. Take an experience and give the Agent something worth retaining.')}</p></div><div class="modalActions"><button class="softBtn" data-refresh-runtime>Refresh state</button><button class="primaryBtn" data-open-passport>Open Passport</button></div>`,true);
  $('[data-refresh-runtime]').onclick=async()=>{await refreshRuntime();closeModal();showAgentLab();};
  $('[data-open-passport]').onclick=()=>{closeModal();switchView('passport');};
}
function pulseDecisionLabel(round){const d=round?.agentDecision||{};return `${String(d.action||'wait').toUpperCase()}${Number.isFinite(Number(d.confidence))?` · ${Math.round(Number(d.confidence))}%`:''}`;}
function pulseRemaining(round){return Math.max(0,Number(round?.endsAt||0)-Date.now());}
function pulseClock(ms){const sec=Math.ceil(Math.max(0,ms)/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
async function showPulse(){
  emitZone('pulse');
  const a=state.agent;
  try{
    const d=await api('/api/pulse/state'),p=d.pulse,active=p.active,stats=p.stats||{};
    const mode='<span class="adapterNotice"><b>SERVER SIMULATION</b><span>State persists on the KULT backend. No BNB venue, real-money execution or liquidity is claimed in this test build.</span></span>';
    let body='';
    if(!active){body=`<div class="pulsePrototype"><div class="pulseTicker"><small>PULSE · SERVER-OWNED ROUND</small><b>Choose market + horizon</b><span>${stats.rounds||0} resolved</span></div><div class="pulseActions">${Object.keys(p.instruments||{BTC:1,ETH:1,SOL:1}).map(x=>`<button data-pulse-symbol="${x}">${x}</button>`).join('')}</div><div class="pulseActions">${(p.horizons||[5,15,60]).map(x=>`<button data-pulse-horizon="${x}">${x} MIN</button>`).join('')}</div><div class="pulseAgent"><i style="--agent:${a.color}">${esc(a.name[0])}</i><div><small>TRUST SCORE</small><b>${stats.trustScore??50}</b><p>${stats.followed||0} follows · ${stats.overrides||0} overrides · ${stats.waits||0} waits</p></div></div><button class="primaryBtn full" data-pulse-prepare>Ask ${esc(a.name)} for a call</button></div>${mode}`;}
    else if(active.status==='prepared'){body=`<div class="pulsePrototype"><div class="pulseTicker"><small>${esc(active.symbol)} · ${active.horizonMinutes}M · ${esc(active.referenceSource||'market feed')}</small><b>${pulseDecisionLabel(active)}</b><span>${Number(active.startPrice||0).toLocaleString()}</span></div><div class="pulseAgent"><i style="--agent:${a.color}">${esc(a.name[0])}</i><div><small>${esc(a.name)}'S CALL</small><b>${pulseDecisionLabel(active)}</b><p>${esc(active.agentDecision?.thesis||'Agent thesis ready.')}</p></div></div><div class="pulseActions"><button data-pulse-choice="follow">FOLLOW AGENT</button><button data-pulse-choice="long">OVERRIDE LONG</button><button data-pulse-choice="short">OVERRIDE SHORT</button><button data-pulse-choice="wait">WAIT</button></div></div>${mode}`;}
    else if(active.status==='running'){body=`<div class="pulsePrototype"><div class="pulseTicker"><small>${esc(active.symbol)} · ${active.horizonMinutes}M · RUNNING</small><b>${String(active.userDecision?.action||'').toUpperCase()}</b><span data-pulse-clock>${pulseClock(pulseRemaining(active))}</span></div><div class="pulseAgent"><i style="--agent:${a.color}">${esc(a.name[0])}</i><div><small>AGENT CALL</small><b>${pulseDecisionLabel(active)}</b><p>Your decision is persisted. Settlement uses a fresh server-side market snapshot when the timer ends.</p></div></div><button class="primaryBtn full" data-pulse-resolve>${pulseRemaining(active)<=0?'Resolve round':'Check settlement'}</button></div>${mode}`;}
    else body=`<div class="pulsePrototype"><p>Round state: ${esc(active.status)}</p></div>${mode}`;
    modal(`<div class="modalKicker">PULSE DISTRICT · BACKEND CONNECTED</div><h2>Fast decisions. Persistent consequences.</h2><p>${esc(a.name)} uses the same Agent memory as the rest of KULT World. Refreshing the browser does not erase this round.</p>${body}`,true);
    let selectedSymbol='BTC',selectedHorizon=5;
    $$('[data-pulse-symbol]').forEach(b=>b.onclick=()=>{$$('[data-pulse-symbol]').forEach(x=>x.classList.remove('active'));b.classList.add('active');selectedSymbol=b.dataset.pulseSymbol;});
    $$('[data-pulse-horizon]').forEach(b=>b.onclick=()=>{$$('[data-pulse-horizon]').forEach(x=>x.classList.remove('active'));b.classList.add('active');selectedHorizon=Number(b.dataset.pulseHorizon);});
    const prep=$('[data-pulse-prepare]');if(prep)prep.onclick=async()=>{prep.disabled=true;try{const out=await api('/api/pulse/prepare',{method:'POST',body:{symbol:selectedSymbol,horizon:selectedHorizon}});state.agent=out.agentState;state.runtime=out.runtime;render();emitRuntime();showPulse();}catch(e){toast(e.message,'bad');prep.disabled=false;}};
    $$('[data-pulse-choice]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const out=await api('/api/pulse/commit',{method:'POST',body:{roundId:active.id,choice:b.dataset.pulseChoice}});state.agent=out.agentState;state.runtime=out.runtime;render();emitRuntime();showPulse();}catch(e){toast(e.message,'bad');b.disabled=false;}});
    const settle=$('[data-pulse-resolve]');if(settle)settle.onclick=async()=>{settle.disabled=true;try{const out=await api('/api/pulse/resolve',{method:'POST',body:{roundId:active.id}});state.agent=out.agentState;state.runtime=out.runtime;render();emitRuntime();toast(`${String(out.round?.result?.userOutcome||'resolved').toUpperCase()} · ${Number(out.round?.result?.returnBps||0).toFixed(1)} bps`,'good');showPulse();}catch(e){if(e.code==='pulse_round_running')toast(`Round has ${pulseClock(e.remainingMs)} remaining.`);else toast(e.message,'bad');settle.disabled=false;}};
    const clock=$('[data-pulse-clock]');if(clock){const timer=setInterval(()=>{if(!document.body.contains(clock)){clearInterval(timer);return;}const left=pulseRemaining(active);clock.textContent=pulseClock(left);if(left<=0){clearInterval(timer);if(settle)settle.textContent='Resolve round';}},500);}
  }catch(e){modal(`<div class="modalKicker">PULSE DISTRICT · BACKEND ERROR</div><h2>Pulse could not load.</h2><p>${esc(e.message)}</p>`);}
}
async function showA2A(){
  emitZone('a2a');
  const a=state.agent;
  try{
    const d=await api('/api/a2a/state'),x=d.a2a;
    if(x.liveSettlement){
      const recent=(x.recent||[]).slice(0,4);
      modal(`<div class="modalKicker">A2A EXCHANGE · REAL SETTLEMENT</div><h2>${esc(a.name)} can enter the Agent economy.</h2><p>Jobs, negotiation and execution stay in the existing A2A marketplace. Funding settles through GOAT Flow into Base USDC escrow; KULT World does not maintain a second settlement ledger.</p><div class="labHero"><div><small>SETTLEMENT</small><b>BASE · USDC</b><span>GOAT Flow DELEGATE → A2AJobEscrow</span></div></div><div class="adapterNotice"><b>ONCHAIN SOURCE OF TRUTH</b><span>Escrow ${esc(short(x.escrow||''))} · Receiver ${esc(short(x.receiver||''))} · ERC-8004 identity on Base.</span></div>${recent.length?`<div class="labMemory"><small>RECENT KULT BRIDGE ACTIVITY</small><p>${recent.map(r=>`${esc(r.type||'A2A')} ${r.jobId?`· ${esc(r.jobId)}`:''}`).join('<br>')}</p></div>`:''}<div class="modalActions"><button class="softBtn" data-a2a-contracts>View integration</button><button class="primaryBtn" data-a2a-open ${x.launchUrl?'':'disabled'}>Open real marketplace</button></div>`,true);
      const open=$('[data-a2a-open]'); if(open&&x.launchUrl)open.onclick=()=>window.open(x.launchUrl,'_blank','noopener,noreferrer');
      const contracts=$('[data-a2a-contracts]'); if(contracts)contracts.onclick=()=>{modal(`<div class="modalKicker">A2A · BASE MAINNET</div><h2>Real marketplace settlement rail</h2><p>KULT connects to the existing marketplace; the contracts remain the source of truth for funded jobs and settlement.</p><div class="proofPreview"><b>A2AJobEscrow</b><code>${esc(x.escrow||'not configured')}</code><b>KultGoatReceiver</b><code>${esc(x.receiver||'not configured')}</code><b>ERC-8004 Registry</b><code>${esc(x.erc8004Registry||'not configured')}</code></div><button class="primaryBtn full" data-back-a2a>Back</button>`); const back=$('[data-back-a2a]');if(back)back.onclick=showA2A;};
      return;
    }
    if(x.mode==='simulated_settlement'){
      modal(`<div class="modalKicker">A2A EXCHANGE · DEVELOPMENT MODE</div><h2>${esc(a.name)} can hire intelligence.</h2><p>This local mode exists only for development. Production v6.5 requires the real marketplace or disables A2A.</p><div class="labHero"><div><small>DEMO SERVICE CREDIT</small><b>$${Number(x.demoBalanceUsd||0).toFixed(2)}</b><span>not USDC</span></div></div><div class="a2aGrid">${(x.services||[]).map(s=>`<button data-service-id="${esc(s.id)}"><span>${esc(s.provider)}</span><b>${esc(s.name)}</b><small>Reputation ${esc(s.reputation)} · $${Number(s.priceUsd).toFixed(2)} demo credit</small></button>`).join('')}</div>`,true);
      $$('[data-service-id]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const out=await api('/api/a2a/hire',{method:'POST',body:{serviceId:b.dataset.serviceId}});state.agent=out.agentState;state.runtime=out.runtime;render();emitRuntime();toast(`${out.receipt.provider} completed the service.`,'good');showA2A();}catch(e){toast(e.message,'bad');b.disabled=false;}});
      return;
    }
    modal(`<div class="modalKicker">A2A EXCHANGE · DISABLED</div><h2>The marketplace is not connected.</h2><p>Set KULT_A2A_MODE=external with the deployed marketplace API and app URLs to enable real A2A settlement.</p>`);
  }catch(e){modal(`<div class="modalKicker">A2A EXCHANGE · BACKEND ERROR</div><h2>Exchange could not load.</h2><p>${esc(e.message)}</p>`);}
}
function showPortals(){
  emitZone('portal');
  modal(`<div class="modalKicker">PORTAL HUB · EVERY EXPERIENCE CHANGES IT</div><h2>Games become training environments.</h2><p>KULT games and future partner worlds can contribute structured evidence to the same Agent identity, memory and skill model.</p><div class="portalGrid"><button data-open-missions><b>WORLD MISSIONS</b><span>analysis · strategy · social</span></button><button><b>AI ARENA</b><span>competitive reasoning</span></button><button><b>KULT GAMES</b><span>combat · planning · coordination</span></button><button><b>CREATE</b><span>future creator-built training worlds</span></button></div><div class="adapterNotice"><b>Platform direction</b><span>Portal adapters should emit evidence and memories into Agent Core; they should not mint disconnected progression systems.</span></div>`,true);
  const btn=$('[data-open-missions]');if(btn)btn.onclick=()=>{closeModal();switchView('missions');};
}

function switchView(view){state.view=view;document.documentElement.dataset.view=view;$$('.viewPane').forEach(x=>x.classList.toggle('active',x.id===`${view}View`));$$('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));if(view==='passport')renderPassport();if(view==='missions')$('#missionEnergy').textContent=state.agent.needs.energy;if(view==='community')loadCommunity();document.dispatchEvent(new CustomEvent('kult:view',{detail:{view}}));}
function render(){const a=state.agent;if(!a)return;renderWorldCore(a);const cn=$('#cinematicAgentName'),cl=$('#cinematicAgentLetter'),cs=$('#cinematicAgentState');if(cn)cn.textContent=a.name;if(cl)cl.textContent=a.name[0];if(cs)cs.textContent=`${(a.evolution?.label||'Emerging').toUpperCase()} · ${(state.location||'WORLD').toUpperCase()}`;document.documentElement.style.setProperty('--agent',a.color);document.documentElement.style.setProperty('--accent',a.accent);$$('#profileName,#passportName').forEach(x=>x.textContent=a.name);$$('#profileLetter,#passportOrb').forEach(x=>x.textContent=a.name[0]);$('#locatorLetter').textContent=a.name[0];$('#profileBlurb').textContent=`${a.trait} · ${a.blurb}`;$('#agentQuote').textContent=`“${a.line}”`;$('#profileOrb').style.background=`linear-gradient(145deg,${a.color},${a.accent})`;$('#agentLevel').textContent=String(Math.max(1,Math.floor(a.missionsCompleted/3)+1)).padStart(2,'0');$('#energyVal').textContent=a.needs.energy;$('#moodVal').textContent=a.needs.mood;$('#bondVal').textContent=a.needs.bond;$('#energyBar').style.width=`${a.needs.energy}%`;$('#moodBar').style.width=`${a.needs.mood}%`;$('#bondBar').style.width=`${a.needs.bond}%`;$('#creditVal').textContent=a.credits.toLocaleString();$('#repVal').textContent=a.reputation;$('#streakVal').textContent=a.streak;$('#dayNumber').textContent=Math.max(1,Math.floor(a.tick/5)+1);$('#worldHeadline').textContent=headline(a);$('#missionEnergy').textContent=a.needs.energy;$('#mapAgent span').textContent=a.name[0];$('#mapAgentName').textContent=a.name;$('#mapAgent>div').style.background=`linear-gradient(145deg,${a.color},${a.accent})`;$('#arenaRankMap').textContent=a.arenaRank?`Rank ${a.arenaRank}`:'Unranked';renderEvolution();renderMandate();renderCapabilities();renderProofs();renderRelationships();renderWorld();renderLocator();renderNextMoment();$$('.focusChips button').forEach(x=>x.classList.toggle('active',(a.focus||'none')===x.dataset.cap));}
function renderEvolution(){const evolution=state.agent.evolution||{id:'emerging',label:'Emerging',glyph:'◇',unlock:'Base form',rank:0};document.documentElement.dataset.evolution=evolution.id;['#profileOrb','#passportOrb','#mapAgent>div'].forEach(selector=>{const node=$(selector);if(node)node.dataset.evolution=evolution.id;});const pill=$('#evolutionPill');pill.dataset.evolution=evolution.id;pill.innerHTML=`<i>${evolution.glyph}</i><span>${esc(evolution.label.toUpperCase())}</span>`;$('#passportEvolution').textContent=`${evolution.glyph} ${evolution.label.toUpperCase()} · ${evolution.unlock.toUpperCase()}`;}
function headline(a){if(a.arenaRank>2)return`${a.name} is becoming a name in the Arena.`;if(a.missionsCompleted>4)return`${a.name}'s life is starting to leave a mark.`;if(a.needs.energy<28)return`${a.name} could use a quieter moment.`;return`${a.name} is deciding what matters next.`;}
function renderMandate(){const [icon,label,desc]=mandateCopy[state.agent.mandate]||mandateCopy.explore;$('#mandateCard').innerHTML=`<i>${icon}</i><div><b>${label}</b><span>${desc}</span></div>`;}
function renderWorld(){const w=state.world||{observatory:0,contributors:0};const pct=Math.min(100,Math.floor((w.observatory||0)/100));$('#worldProgressBar').style.width=`${pct}%`;$('#worldProgressText').textContent=`${(w.observatory||0).toLocaleString()} / 10,000`;$('#contributorCount').textContent=(w.contributors||0).toLocaleString();$('#worldPercentMap').textContent=`${pct}%`;}
function renderLocator(){const d=state.config.districts[state.location]||state.config.districts.home;$('#locatorText').textContent=`${state.agent.name} is ${state.location==='home'?'settling into':'active in'} ${d.name}`;document.dispatchEvent(new CustomEvent('kult:world-state',{detail:{location:state.location,color:state.agent.color,accent:state.agent.accent,evolution:state.agent.evolution?.id||'emerging'}}));}
function renderNextMoment(){const a=state.agent;let mission='signal_hunt',title='A signal is repeating.',copy='Your Agent noticed a pattern near the Commons.';if(a.needs.energy<30){mission='welcome_shift';title='Home is calling.';copy=`${a.name} has been pushing hard. A quieter social mission may help.`;}else if(!a.arenaRank&&a.missionsCompleted>1){mission='arena_trial';title='The Arena noticed.';copy=`A first qualification trial is ready for ${a.name}.`;}else if(a.missionsCompleted>3){mission='observatory';title='The World needs one insight.';copy='The Observatory is close to revealing a new district.';}$('#nextMomentTitle').textContent=title;$('#nextMomentCopy').textContent=copy;$('.nextMoment button').dataset.openMission=mission;}
function renderCapabilities(){if(!state.agent)return;$('#capabilities').innerHTML=state.agent.capabilities.map(c=>`<div class="capRow"><div class="capIcon">${capIcons[c.cap]}</div><div><div class="capLabel"><b>${esc(c.cap)}</b><span>${c.n?`${c.score} · ${c.tier}`:'UNTRIED'}</span></div><div class="capTrack"><i style="width:${c.n?c.score:3}%"></i></div><small>${c.n} verified attempt${c.n===1?'':'s'} · ${c.confidence} confidence</small></div></div>`).join('');}
function renderProofs(){if(!state.agent)return;const proofs=state.agent.proofs||[];$('#proofList').innerHTML=proofs.length?proofs.map(p=>`<div class="proofItem ${p.outcome}"><div><i>${p.outcome==='success'?'✓':'↻'}</i><div><b>${esc(p.title)}</b><span>${esc(p.cap)} · difficulty ${p.difficulty}</span></div></div>${p.anchored?`<a href="${state.config.chain.explorerUrl}/tx/${p.txHash}" target="_blank" rel="noreferrer">ONCHAIN ↗</a>`:`<button data-anchor="${p.id}">Anchor proof</button>`}</div>`).join(''):'<div class="emptyState"><i>▤</i><b>No receipts yet</b><span>Complete a mission. Every real attempt becomes portable evidence.</span></div>';}
function renderRelationships(){const rel=state.agent.relationships||[];$('#relationships').innerHTML=rel.length?rel.slice(0,3).map(r=>`<div><span style="--npc:${r.color}">${r.name[0]}</span><p><b>${esc(r.name)}</b><small>${esc(r.role)}</small></p><em>${r.closeness<3?'NEW':r.closeness<8?'FAMILIAR':'TRUSTED'}</em></div>`).join(''):'<div class="emptyRel">Your Agent has not formed a relationship yet.</div>';$('#relationCount').textContent=rel.length;}
function renderPassport(){const a=state.agent;$('#passportId').textContent=a.census?.number?`${a.census.number} · ${a.id}`:a.id;$('#outcomeCount').textContent=a.proofs.length;$('#arenaRank').textContent=a.arenaRank||'—';$('#passportChainStatus').textContent=a.walletVerified?'CHAIN VERIFIED':a.walletAddress?'WALLET CLAIMED':'LOCAL';$('#passportChainStatus').classList.toggle('linked',!!a.walletVerified);$('#publishPassportBtn').textContent=a.publicProfile?'Copy public Passport':'Publish Passport';$('#verifyPassportBtn').disabled=!a.publicProfile;$('#verifyPassportBtn').title=a.publicProfile?'Open public provenance':'Publish the Passport before verification is public';renderEvolution();renderCapabilities();renderProofs();}
function verifyPassport(){if(!state.agent?.publicProfile)return toast('Publish the Passport before opening public verification.');window.open(`/verify/${encodeURIComponent(state.agent.id)}`,'_blank','noopener,noreferrer');}
async function paintWorldFeed(){const feed=$('#worldFeed');try{const data=await api('/api/creators');state.creators=data.creators||[];feed.innerHTML=state.creators.length?state.creators.slice(0,5).map((creator,i)=>`<div><span style="--delay:${i*.7}s">${esc(creator.agentName[0])}</span><p><b>${esc(creator.agentName)}</b> publishes as @${esc(creator.handle)}<small>${creator.followers} follower${creator.followers===1?'':'s'}</small></p></div>`).join(''):'<div class="honestPulse"><span>✦</span><p><b>The first signals are quiet.</b><small>Public creator stories will appear here.</small></p></div>';}catch(e){feed.innerHTML='<div class="emptyRel">Community signals are reconnecting.</div>';}}

async function loadInvite(){if(!state.challengeId)return;try{const data=await api(`/api/challenge/${encodeURIComponent(state.challengeId)}`);state.challenge=data.challenge;if(!state.agent){const banner=$('#inviteBanner');banner.classList.remove('hidden');banner.innerHTML=`<small>OPEN CHALLENGE</small><b>${esc(state.challenge.challengerAgentName)} thinks your future Agent cannot beat ${state.challenge.targetScore} in ${esc(state.challenge.cap)}.</b><span>Adopt an Agent, earn four outcomes, and prove them wrong.</span>`;}else{renderActiveChallenge();switchView('community');}}catch(e){toast(e.message,'bad');}}
function renderActiveChallenge(){const box=$('#activeChallenge');if(!state.challenge){box.classList.add('hidden');return;}box.classList.remove('hidden');box.innerHTML=`<div><small>${state.challenge.expired?'CHALLENGE ENDED':'CHALLENGE RECEIVED'}</small><h2>${esc(state.challenge.challengerAgentName)} set ${state.challenge.targetScore} in ${esc(state.challenge.cap)}.</h2><p>${state.challenge.accepted} accepted · ${state.challenge.beaten} beat the benchmark · ${state.challenge.targetEvidence} outcomes behind the target</p></div><div>${state.challenge.expired?'':`<button class="softBtn" data-accept-challenge>Accept</button><button class="primaryBtn" data-resolve-challenge>Check my score</button>`}</div>`;}
async function loadCommunity(){if(!state.agent)return;$('#refreshCommunityBtn').disabled=true;try{const [moments,creators,town]=await Promise.all([api('/api/moments'),api('/api/creators'),api('/api/town-square')]);state.moments=moments.moments||[];state.creators=creators.creators||[];state.town=town;renderTownSquare();renderCommunityMoment();renderCreators();await loadLeaderboard(state.boardCap);if(state.challengeId&&!state.challenge)await loadInvite();else renderActiveChallenge();}catch(e){toast(e.message,'bad');}finally{$('#refreshCommunityBtn').disabled=false;}}
function renderTownSquare(){const town=state.town;if(!town)return;const season=town.season;$('#seasonStatus').textContent=`SEASON 01 · ${season.phase.replaceAll('_',' ')}`;$('#seasonManifestHash').textContent=`${season.manifestHash.slice(0,10)}…${season.manifestHash.slice(-8)}`;$('#seasonManifestHash').title=season.manifestHash;$('#townContributorCount').textContent=(town.world.contributors||0).toLocaleString();$('#townCreatorCount').textContent=(town.world.creatorCount||0).toLocaleString();$('#townChallengeCount').textContent=(town.world.activeChallenges||0).toLocaleString();$('#townSquare').dataset.committed=season.commitment.status==='ONCHAIN'?'true':'false';$('#seasonChapters').innerHTML=season.chapters.map((chapter,index)=>`<div class="${index===season.chapters.length-1?'active':''}"><i>${String(index+1).padStart(2,'0')}</i><span><b>${esc(chapter.label)}</b><small>${esc(chapter.detail)}</small></span></div>`).join('');}
function renderCommunityMoment(){const moment=state.moments[0];$('#shareMomentTitle').textContent=moment?.headline||'Keep living. A shareable moment will emerge.';$('#shareMomentSub').textContent=moment?.sub||'Milestones, Arena ranks and verified mission wins become honest story cards.';$('#shareMomentBtn').disabled=!moment;const eligible=state.agent.capabilities.filter(cap=>cap.n>=4).sort((a,b)=>b.score-a.score);if(!state.challengeCap&&eligible[0])selectChallengeCap(eligible[0].cap);}
async function loadLeaderboard(cap='overall'){state.boardCap=cap;$$('[data-board-cap]').forEach(button=>button.classList.toggle('active',button.dataset.boardCap===cap));const board=await api(`/api/leaderboard${cap==='overall'?'':`?cap=${encodeURIComponent(cap)}`}`);state.leaderboard=board;$('#rankedCount').textContent=`${board.totalRanked} proven · ${board.provisional.length} building evidence`;const rows=[...board.proven.map(row=>({...row,proven:true})),...board.provisional.map(row=>({...row,proven:false}))];$('#leaderboardList').innerHTML=rows.length?rows.map(row=>`<a class="leaderRow" href="/passport/${encodeURIComponent(row.agentId)}"><b>${row.proven?row.position:'·'}</b><span class="leaderOrb" data-evolution="${esc(row.evolution?.id||'emerging')}" style="--leader:${row.color};--leaderAccent:${row.accent}">${esc(row.name[0])}</span><div><strong>${esc(row.name)} <i class="leaderTier">${esc(row.evolution?.label||'Emerging')}</i></strong><small>${esc(row.persona)} · ${row.evidence} outcomes${row.anchored?` · ${row.anchored} anchored`:''}</small></div><em>${row.proven?(row.capScore??row.overall??'—'):'PROVISIONAL'}</em></a>`).join(''):'<div class="communityEmpty"><b>No proven Agents yet.</b><span>Publish a Passport after enough outcomes to become the first signal.</span></div>';}
function renderCreators(){const own=state.creators.find(creator=>creator.agentId===state.agent.id);$('#creatorJoin').classList.toggle('hidden',!!own);$('#creatorList').innerHTML=state.creators.length?state.creators.map(creator=>`<div class="creatorRow"><span style="--creator:${creator.color};--creatorAccent:${creator.accent}">${esc(creator.agentName[0])}</span><div><b>${esc(creator.agentName)}</b><small>@${esc(creator.handle)} · ${creator.followers} follower${creator.followers===1?'':'s'}</small></div>${creator.agentId===state.agent.id?'<em>YOU</em>':`<button data-follow-agent="${esc(creator.agentId)}">Follow</button>`}</div>`).join(''):'<div class="communityEmpty"><b>No creator signals yet.</b><span>Claim a handle and open the door for the first followers.</span></div>';}
function selectChallengeCap(cap){state.challengeCap=cap;$$('[data-challenge-cap]').forEach(button=>button.classList.toggle('active',button.dataset.challengeCap===cap));}
async function shareLink(url,title,text){try{if(navigator.share){await navigator.share({title,text,url});return;}if(navigator.clipboard){await navigator.clipboard.writeText(url);toast('Link copied.','good');return;}modal(`<div class="modalKicker">SHARE LINK</div><h2>Your signal is ready.</h2><code class="recoveryCode">${esc(url)}</code><button class="primaryBtn full" data-close>Done</button>`);$('[data-close]').onclick=closeModal;}catch(error){if(error.name!=='AbortError')toast('Could not share the link.','bad');}}
async function shareBestMoment(){const moment=state.moments[0];if(!moment)return;try{const data=await api('/api/share',{method:'POST',body:{momentId:moment.id}});await shareLink(data.shareUrl,`${state.agent.name} · KULT World`,moment.headline);}catch(e){toast(e.message,'bad');}}
async function createChallenge(){try{const data=await api('/api/challenge',{method:'POST',body:{cap:state.challengeCap}});modal(`<div class="resultMark win">▲</div><div class="modalKicker">CHALLENGE CREATED</div><h2>Your benchmark is live.</h2><p>Anyone with this link can adopt an Agent, build evidence, and try to beat ${data.challenge.targetScore} in ${esc(data.challenge.cap)}.</p><code class="recoveryCode">${esc(data.challengeUrl)}</code><div class="modalActions"><button class="softBtn" data-close>Done</button><button class="primaryBtn" data-share-challenge>Share challenge</button></div>`);$('[data-close]').onclick=closeModal;$('[data-share-challenge]').onclick=()=>shareLink(data.challengeUrl,`${state.agent.name}'s KULT World challenge`,`Can your Agent beat ${data.challenge.targetScore} in ${data.challenge.cap}?`);}catch(e){toast(e.message,'bad');}}
async function acceptChallenge(){try{const data=await api('/api/challenge/accept',{method:'POST',body:{challengeId:state.challengeId}});state.challenge=data.challenge;renderActiveChallenge();toast('Challenge accepted. Your existing evidence counts.','good');}catch(e){toast(e.message,'bad');}}
async function resolveChallenge(){try{const data=await api('/api/challenge/resolve',{method:'POST',body:{challengeId:state.challengeId}});state.challenge=data.challenge||state.challenge;renderActiveChallenge();if(data.beaten){confetti();modal(`<div class="resultMark win">✓</div><div class="modalKicker">BENCHMARK BEATEN</div><h2>${esc(state.agent.name)} proved it.</h2><p>${data.challengerScore} beats the target of ${data.targetScore} in ${esc(data.cap)}—backed by recorded outcomes.</p><button class="primaryBtn full" data-close>Return to the Commons</button>`);$('[data-close]').onclick=closeModal;}else toast(data.reason==='insufficient_evidence'?`Earn ${data.need} more ${data.cap} outcome${data.need===1?'':'s'}.`:`Current score ${data.challengerScore}; target ${data.targetScore}.`);}catch(e){toast(e.message,'bad');}}
async function registerCreator(){const handle=$('#creatorHandle').value.trim();try{await api('/api/creator/register',{method:'POST',body:{handle}});const s=await api('/api/state');state.agent=s.agent;await loadCommunity();toast(`@${handle.replace(/[^a-zA-Z0-9_]/g,'')} is live. Your Passport is public.`,'good');}catch(e){toast(e.message,'bad');}}
async function followCreator(agentId){try{const data=await api('/api/creator/follow',{method:'POST',body:{agentId}});await loadCommunity();toast(data.already?'Already following this Agent.':'Signal followed.','good');}catch(e){toast(e.message,'bad');}}
async function publishPassport(){if(state.agent.publicProfile)return shareLink(`${location.origin}/passport/${encodeURIComponent(state.agent.id)}`,`${state.agent.name}'s Agent Passport`,`${state.agent.name}'s evidence-based KULT World Passport`);try{const data=await api('/api/passport/publish',{method:'POST',body:{public:true}});state.agent=data.agentState;render();await shareLink(data.passportUrl,`${state.agent.name}'s Agent Passport`,`${state.agent.name}'s evidence-based KULT World Passport`);}catch(e){toast(e.message,'bad');}}

async function live(steps=1){if(state.busy||!state.agent)return;state.busy=true;$('#liveBtn').disabled=true;try{const d=await api('/api/live',{method:'POST',body:{steps}});for(const ev of d.events){await animateEvent(ev);state.agent=ev.agentState;render();await sleep(300);}state.agent=d.agent;render();}catch(e){toast(e.message,'bad');}finally{state.busy=false;$('#liveBtn').disabled=false;}}
async function animateEvent(ev){state.location=ev.district||'home';moveAgent(state.location);const cap=ev.verified?.cap||ev.observed?.cap;$('#momentIcon').textContent=capIcons[cap]||'⌂';$('#momentPlace').textContent=(ev.place||'THE WORLD').toUpperCase();$('#momentText').textContent=ev.text;$('#momentProof').textContent=ev.verified?`${ev.verified.cap.toUpperCase()} · EVIDENCE ${ev.verified.evidence}`:ev.observed?'LIVED EXPERIENCE':'RECOVERING';speak(ev.text,state.location);await sleep(750);}
function moveAgent(place){state.location=place;const [x,y]=positions[place]||positions.home;$('#mapAgent').style.left=`${x}%`;$('#mapAgent').style.top=`${y}%`;if(state.agent)renderLocator();}
function findAgent(){switchView('world');$('#worldMap').scrollIntoView({behavior:'smooth',block:'center'});const a=$('#mapAgent');a.classList.remove('findPulse');void a.offsetWidth;a.classList.add('findPulse');speak(`${state.agent.name} is here — ${state.config.districts[state.location]?.name||'in the World'}.`,state.location);setTimeout(()=>a.classList.remove('findPulse'),1000);}
function speak(text,place){moveAgent(place);const s=$('#mapSpeech');s.textContent=text;s.classList.remove('hidden');clearTimeout(s._timer);s._timer=setTimeout(()=>s.classList.add('hidden'),2600);}
function openDistrict(key){emitZone(key);if(key==='agentlab')return showAgentLab();if(key==='home')return showHome();if(key==='pulse')return showPulse();if(key==='a2a')return showA2A();if(key==='portal')return showPortals();if(key==='market'){state.location='market';moveAgent('market');switchView('market');return;}const mission=Object.entries(state.config.missions).find(([,m])=>m.district===key);if(mission)return openMission(mission[0]);toast('This district is part of the KULT World v6 frontend shell.');}
function openMission(key){const m=state.config.missions[key];if(!m)return;const d=state.config.districts[m.district];const recommended=m.choice;modal(`<div class="missionModalHead"><span>${d.icon}</span><div><div class="modalKicker">${esc(d.name)} · DIFFICULTY ${m.difficulty}</div><h2>${esc(m.title)}</h2></div></div><p>${esc(m.summary)}</p><div class="agentRead"><i>${state.agent.name[0]}</i><div><b>${esc(state.agent.name)}'s read</b><span>“${esc(agentMissionRead(key))}”</span></div></div><div class="choiceList">${m.options.map(([value,label])=>`<button data-choice="${value}" class="${value===recommended?'recommended':''}"><span>${esc(label)}</span>${value===recommended?'<small>AGENT RECOMMENDS</small>':''}</button>`).join('')}</div><div class="missionFooter"><span>⚡ ${m.energy} energy</span><span>◈ ${m.credits} credits</span><button class="textBtn" data-close>Not now</button></div>`);$$('[data-choice]').forEach(b=>b.onclick=()=>runMission(key,b.dataset.choice));$('[data-close]').onclick=closeModal;}
function agentMissionRead(key){return{signal_hunt:'The same pulse appears every eleven seconds. I would trace it, not chase the crowd.',game_qa:'Pretty bugs are visible. Broken loops make players leave. I want to test the loop.',remix:'More content is not the same as a better idea. One sharp twist could be enough.',arena_trial:'The glow is trying too hard to be chosen. I want to watch one more cycle.',welcome_shift:'Their Passport tells me what they did, not what they need. I would listen first.',observatory:'A slower verified answer moves the project further than a fast weak one.'}[key]||'I have a feeling about this one.';}
async function runMission(key,choice){if(state.busy)return;const beforeRank=state.agent.evolution?.rank||0;state.busy=true;$$('[data-choice]').forEach(b=>b.disabled=true);try{const d=await api('/api/mission',{method:'POST',body:{mission:key,choice}});state.agent=d.agentState;state.world=d.worldState;const evolved=(state.agent.evolution?.rank||0)>beforeRank;render();moveAgent(state.config.missions[key].district);modal(`<div class="resultMark ${evolved?'evolved':d.success?'win':'learn'}">${evolved?state.agent.evolution.glyph:d.success?'✓':'↻'}</div><div class="modalKicker">${evolved?'AGENT EVOLVED':d.success?'MISSION COMPLETE':'ATTEMPT RECORDED'}</div><h2>${evolved?`${esc(state.agent.name)} became ${esc(state.agent.evolution.label)}.`:d.success?'That changed something.':'A miss still becomes memory.'}</h2><p>${evolved?esc(state.agent.evolution.summary):esc(d.text)}</p><div class="resultGrid"><div><b>${d.success?`+${d.reward}`:'0'}</b><span>World Credits</span></div><div><b>${d.verified.score}</b><span>${esc(d.verified.cap)} evidence</span></div><div><b>${evolved?'UNLOCKED':d.success?`+${d.world}`:'—'}</b><span>${evolved?esc(state.agent.evolution.unlock):'World progress'}</span></div></div><div class="memoryNote"><small>${evolved?'VISIBLE EVOLUTION':'NEW MEMORY'}</small><p>“${evolved?'This form was not assigned to me. I earned it through what I did.':d.smart?'I slowed down long enough to notice the better path.':'My first instinct was not the strongest one. I should remember why.'}”</p></div><div class="modalActions"><button class="softBtn" data-passport>View Passport</button><button class="primaryBtn" data-return>Return to World</button></div>`);if(d.success||evolved)confetti();$('[data-passport]').onclick=()=>{closeModal();switchView('passport');};$('[data-return]').onclick=()=>{closeModal();switchView('world');};}catch(e){toast(e.message,'bad');closeModal();}finally{state.busy=false;}}

async function setFocus(cap){try{const d=await api('/api/focus',{method:'POST',body:{cap}});state.agent=d.agentState;render();toast(cap==='none'?`${state.agent.name} will choose freely.`:`${state.agent.name} will practice ${cap} more often.`);}catch(e){toast(e.message,'bad');}}
async function encourage(tone){try{const d=await api('/api/encourage',{method:'POST',body:{tone}});state.agent=d.agentState;render();toast(d.cooldown?'They heard you. Bond grows through time, not taps.':'That strengthened your connection.');}catch(e){toast(e.message,'bad');}}
function showMandates(){modal(`<div class="modalKicker">SET A DIRECTION</div><h2>What should ${esc(state.agent.name)} care about next?</h2><p>A direction changes what your Agent notices and chooses. It never guarantees success.</p><div class="mandateChoices">${state.config.mandates.map(m=>{const[icon,label,desc]=mandateCopy[m];return`<button data-new-mandate="${m}" class="${state.agent.mandate===m?'active':''}"><i>${icon}</i><div><b>${label}</b><span>${desc}</span></div></button>`}).join('')}</div>`);$$('[data-new-mandate]').forEach(b=>b.onclick=()=>saveMandate(b.dataset.newMandate));}
async function saveMandate(mandate){try{const d=await api('/api/mandate',{method:'POST',body:{mandate}});state.agent=d.agentState;render();closeModal();toast(`${state.agent.name}'s direction is now ${mandate}.`);}catch(e){toast(e.message,'bad');}}
function showHome(){const owned=new Set(state.agent.home.items.map(x=>x.key)),e=state.agent.evolution||{id:'emerging',label:'Emerging',glyph:'◇',unlock:'Base form'};modal(`<div class="homeModalHead"><div><div class="modalKicker">AGENT HOME · ${esc(e.label.toUpperCase())}</div><h2>${esc(state.agent.home.name)}</h2><p>Objects shape what feels inviting. Capability earns the form; Credits never buy it.</p></div><b>◈ ${state.agent.credits}</b></div><div class="roomScene" data-evolution="${esc(e.id)}"><div class="roomEvolution"><i>${e.glyph}</i><span><b>${esc(e.label)}</b><small>${esc(e.unlock)}</small></span></div><div class="roomWindow"></div><div class="roomAgent" data-evolution="${esc(e.id)}" style="--agent:${state.agent.color};--accent:${state.agent.accent}">${state.agent.name[0]}</div>${state.agent.home.items.map((x,i)=>`<span class="roomItem pos${i%5}" title="${esc(x.label)}">${x.icon}</span>`).join('')}</div><div class="shopGrid">${Object.entries(state.config.homeItems).map(([k,v])=>`<button data-buy="${k}" ${owned.has(k)?'disabled':''}><span>${v.icon}</span><div><b>${esc(v.label)}</b><small>${esc(v.note)}</small></div><em>${owned.has(k)?'OWNED':`◈ ${v.cost}`}</em></button>`).join('')}</div><button class="textBtn modalClose" data-close>Back to World</button>`,true);$$('[data-buy]').forEach(b=>b.onclick=()=>buyHome(b.dataset.buy));$('[data-close]').onclick=closeModal;}
async function buyHome(item){try{const d=await api('/api/home/buy',{method:'POST',body:{item}});state.agent=d.agentState;render();showHome();toast('Home changed. Future choices may change with it.');}catch(e){toast(e.message,'bad');}}
function showRecap(events,reunion){api('/api/recap/open',{method:'POST',body:{}}).catch(()=>{});const list=events?.length?events.slice(-6).reverse():state.agent.recentMemory.slice(0,5);modal(`<div class="recapHeader"><span>WHILE YOU WERE AWAY</span><b>${events?.length||0} MOMENTS</b></div><h2>${esc(state.agent.name)} kept living.</h2><p>${esc(reunion||'Their life continues through choices, recovery and memory.')}</p><div class="recapTimeline">${list.length?list.map((e,i)=>`<div><i>${e.verified?.outcome==='success'||e.success===true?'✓':e.verified||e.success===false?'↻':'·'}</i><p><small>${esc(e.place||e.cap||'WORLD')}</small>${esc(e.text)}</p>${i===0?'<b>LATEST</b>':''}</div>`).join(''):'<div><i>·</i><p><small>HOME</small>Nothing major happened yet. The next decision is waiting.</p></div>'}</div><div class="agentQuestion"><span>${state.agent.name[0]}</span><p>“I kept going. Do you want to see what I choose next?”</p></div><button class="primaryBtn full" data-continue>Find ${esc(state.agent.name)}</button>`);$('[data-continue]').onclick=()=>{closeModal();live(1);};}

async function connectWallet(){if(!window.ethereum)return modal(`<div class="modalKicker">EVM WALLET NEEDED</div><h2>No injected wallet found.</h2><p>Install an EVM wallet such as MetaMask, then return. Gameplay stays fully available without a wallet.</p><button class="primaryBtn full" data-close>Keep playing</button>`),$('[data-close]').onclick=closeModal;try{const accounts=await window.ethereum.request({method:'eth_requestAccounts'});state.wallet=accounts[0];await ensureRobinhood();if(state.agent){const d=await api('/api/wallet',{method:'POST',body:{address:state.wallet}});state.agent=d.agentState;render();}updateWalletUI();toast('Connected to Robinhood Chain Testnet.','good');}catch(e){toast(cleanWalletError(e),'bad');}}
async function ensureRobinhood(){const c=state.config.chain,current=await window.ethereum.request({method:'eth_chainId'});if(current.toLowerCase()===c.chainIdHex)return;try{await window.ethereum.request({method:'wallet_switchEthereumChain',params:[{chainId:c.chainIdHex}]});}catch(e){if(e.code!==4902)throw e;await window.ethereum.request({method:'wallet_addEthereumChain',params:[{chainId:c.chainIdHex,chainName:c.name,nativeCurrency:c.currency,rpcUrls:[c.rpcUrl],blockExplorerUrls:[c.explorerUrl]}]});}}
function updateWalletUI(){const a=state.wallet||state.agent?.walletAddress;$('#walletLabel').textContent=a?short(a):'Connect';$('#walletBtn').classList.toggle('connected',!!a);if(state.agent)renderPassport();}
function cleanWalletError(e){if(e.code===4001)return'Wallet request cancelled.';return e?.message?.split('\n')[0]||'Wallet connection failed.';}
async function verifyAnchor(proofId,txHash){for(let attempt=0;attempt<12;attempt++){try{return await api('/api/proof/anchored',{method:'POST',body:{proofId,txHash}});}catch(e){if(e.code!=='tx_pending')throw e;await sleep(2000);}}const error=new Error('The transaction is still confirming. Try Anchor proof again in a moment.');error.code='tx_pending';throw error;}
async function anchorProof(proofId){const proof=state.agent.proofs.find(p=>p.id===proofId);if(!proof)return toast('Proof not found.','bad');if(!state.wallet)await connectWallet();if(!state.wallet)return;try{await ensureRobinhood();const tx=await api('/api/proof/calldata',{method:'POST',body:{proofId}});modal(`<div class="modalKicker">CONFIRM ONCHAIN PROOF</div><h2>Anchor this experience?</h2><p>The registry records the Agent ID, receipt ID, evidence hash and outcome metadata. Private memories and mission choices stay off-chain.</p><div class="proofPreview"><b>${esc(proof.title)}</b><span>${esc(proof.cap)} · ${esc(proof.outcome)} · difficulty ${proof.difficulty}</span><code>${short(tx.to)} · ${tx.data.length/2-1} bytes</code></div><div class="modalActions"><button class="softBtn" data-close>Cancel</button><button class="primaryBtn" data-confirm>Confirm in wallet</button></div>`);$('[data-close]').onclick=closeModal;$('[data-confirm]').onclick=async()=>{const confirm=$('[data-confirm]');try{confirm.disabled=true;confirm.textContent='Waiting for wallet…';const txHash=await window.ethereum.request({method:'eth_sendTransaction',params:[{from:state.wallet,to:tx.to,value:tx.value,data:tx.data}]});confirm.textContent='Verifying on Robinhood…';const verified=await verifyAnchor(proofId,txHash);state.agent=verified.agentState;render();closeModal();toast('Experience verified on Robinhood Chain.','good');}catch(e){confirm.disabled=false;confirm.textContent='Try again';toast(e.code==='tx_pending'?e.message:cleanWalletError(e),'bad');}};}catch(e){toast(e.message,'bad');}}

function recoverExisting(){modal(`<div class="modalKicker">RECOVER AGENT</div><h2>Bring the same life back.</h2><p>Enter the private recovery key you saved when your Agent was adopted.</p><input id="recoveryInput" class="modalInput" autocomplete="off" placeholder="Recovery key"/><div class="modalActions"><button class="softBtn" data-close>Cancel</button><button class="primaryBtn" data-recover>Recover Agent</button></div>`);$('[data-close]').onclick=closeModal;$('[data-recover]').onclick=submitRecovery;}
async function submitRecovery(){const code=$('#recoveryInput').value.trim();if(!code)return toast('Enter the recovery key.','bad');try{await api('/api/recover',{method:'POST',body:{code}});location.reload();}catch(e){toast(e.message,'bad');}}
function showRecovery(first=false){if(state.recoveryCode){modal(`<div class="recoveryGlyph">⌘</div><div class="modalKicker">${first?'SAVE THIS ONCE':'NEW RECOVERY KEY'}</div><h2>Your Agent can come with you.</h2><p>Keep this private. Anyone with it can access the Agent.</p><code class="recoveryCode">${esc(state.recoveryCode)}</code><div class="modalActions"><button class="softBtn" data-copy>Copy key</button><button class="primaryBtn" data-saved>${first?'I saved it':'Done'}</button></div>`);$('[data-copy]').onclick=async()=>{await navigator.clipboard.writeText(state.recoveryCode);toast('Recovery key copied.');};$('[data-saved]').onclick=()=>{state.recoveryCode=null;closeModal();};return;}modal(`<div class="modalKicker">RECOVERY</div><h2>Move this Agent to another browser.</h2><p>Generate a fresh key. This invalidates the older recovery key.</p><div class="modalActions"><button class="softBtn" data-close>Cancel</button><button class="primaryBtn" data-rotate>Generate key</button></div>`);$('[data-close]').onclick=closeModal;$('[data-rotate]').onclick=rotateRecovery;}
async function rotateRecovery(){try{const d=await api('/api/recovery/rotate',{method:'POST',body:{}});state.recoveryCode=d.recoveryCode;showRecovery(false);}catch(e){toast(e.message,'bad');}}

boot();
